-- Local development seed, loaded by `supabase db reset` against the local stack only.
-- Never run this against a hosted project. All accounts are fictional and use the
-- reserved example.test domain; the shared password is for local sign-in only.
--
--   Teacher: teacher@example.test / local-dev-password  (portal: /teacher)
--   Student: student@example.test / local-dev-password  (portal: /student)
--
-- Profiles are created by the signup trigger from raw_user_meta_data.signup_portal.
-- Practices are not seeded: publication requires narration generated by the
-- read-aloud function, so create them through the teacher UI.

insert into auth.users (
  instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
  raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
  confirmation_token, recovery_token, email_change, email_change_token_new
)
values
  ('00000000-0000-0000-0000-000000000000', '10000000-0000-4000-8000-000000000001',
   'authenticated', 'authenticated', 'teacher@example.test',
   extensions.crypt('local-dev-password', extensions.gen_salt('bf')), now(),
   '{"provider":"email","providers":["email"]}', '{"signup_portal":"teacher"}',
   now(), now(), '', '', '', ''),
  ('00000000-0000-0000-0000-000000000000', '20000000-0000-4000-8000-000000000001',
   'authenticated', 'authenticated', 'student@example.test',
   extensions.crypt('local-dev-password', extensions.gen_salt('bf')), now(),
   '{"provider":"email","providers":["email"]}', '{"signup_portal":"student"}',
   now(), now(), '', '', '', '');

insert into auth.identities (
  id, provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at
)
select gen_random_uuid(), u.id::text, u.id,
  jsonb_build_object('sub', u.id::text, 'email', u.email, 'email_verified', true),
  'email', now(), now(), now()
from auth.users u
where u.email in ('teacher@example.test', 'student@example.test');

insert into public.classes (teacher_id, name)
values ('10000000-0000-4000-8000-000000000001', 'Room 12 Readers');

insert into public.class_memberships (class_id, teacher_id, student_id)
select c.id, c.teacher_id, '20000000-0000-4000-8000-000000000001'
from public.classes c
where c.teacher_id = '10000000-0000-4000-8000-000000000001';
